create table appointment (id bigint generated by default as identity, created_at timestamp(6) with time zone, customer_id bigint, end_time timestamp(6), start_time timestamp(6), status_id integer, user_id bigint, primary key (id));
create table customer (customer_id bigint not null, created_at timestamp(6) with time zone, full_name varchar(255), phone varchar(255), user_id bigint, primary key (customer_id));
create table permissions (id bigint generated by default as identity, created_at timestamp(6) with time zone, created_by varchar(100), deleted boolean not null, updated_at timestamp(6) with time zone, updated_by varchar(100), description varchar(255), name varchar(100) not null, primary key (id));
create table refresh_token (refresh_token_id bigint generated by default as identity, expires_at timestamp(6) with time zone not null, ip_address varchar(64), issued_at timestamp(6) with time zone not null, replaced_by bigint, revoked boolean not null, token_hash varchar(64) not null, user_agent varchar(512), user_id bigint not null, primary key (refresh_token_id));
create table role_permissions (id bigint generated by default as identity, permission_id bigint, role_id bigint, primary key (id));
create table roles (role_id bigint generated by default as identity, created_at timestamp(6) with time zone, created_by varchar(100), deleted boolean not null, updated_at timestamp(6) with time zone, updated_by varchar(100), description varchar(255), name varchar(50) not null, primary key (role_id));
create table status_appointment (status_id integer not null, create_at timestamp(6) with time zone, nombre varchar(255), primary key (status_id));
create table user_app (user_id bigint generated by default as identity, created_at timestamp(6) with time zone, created_by varchar(100), deleted boolean not null, updated_at timestamp(6) with time zone, updated_by varchar(100), active boolean not null, email varchar(255) not null, name varchar(255), password varchar(255), username varchar(255) not null, primary key (user_id));
create table user_roles (id bigint generated by default as identity, role_id bigint, user_id bigint, primary key (id));
alter table if exists permissions drop constraint if exists uk_permissions_name;
alter table if exists permissions add constraint uk_permissions_name unique (name);
alter table if exists refresh_token drop constraint if exists uk_refresh_token_token_hash;
alter table if exists refresh_token add constraint uk_refresh_token_token_hash unique (token_hash);
alter table if exists roles drop constraint if exists uk_roles_name;
alter table if exists roles add constraint uk_roles_name unique (name);
alter table if exists user_app drop constraint if exists uk_user_app_username;
alter table if exists user_app add constraint uk_user_app_username unique (username);
alter table if exists user_app drop constraint if exists uk_user_app_email;
alter table if exists user_app add constraint uk_user_app_email unique (email);
create sequence customer_seq start with 1 increment by 50;
create sequence status_appointment_seq start with 1 increment by 50;
alter table if exists appointment add constraint fk_appointment_customer foreign key (customer_id) references customer;
alter table if exists appointment add constraint fk_appointment_status foreign key (status_id) references status_appointment;
alter table if exists appointment add constraint fk_appointment_user foreign key (user_id) references user_app;
alter table if exists customer add constraint fk_customer_user foreign key (user_id) references user_app;
alter table if exists refresh_token add constraint fk_refresh_token_user foreign key (user_id) references user_app;
alter table if exists role_permissions add constraint fk_role_permissions_permission foreign key (permission_id) references permissions;
alter table if exists role_permissions add constraint fk_role_permissions_role foreign key (role_id) references roles;
alter table if exists user_roles add constraint fk_user_roles_role foreign key (role_id) references roles;
alter table if exists user_roles add constraint fk_user_roles_user foreign key (user_id) references user_app;
